import{_ as a,r as l,o as d,c as i,b as e,d as t,e as o,a as n}from"./app-79fb6bf2.js";const c={},r=n('<h1 id="docker学习记录" tabindex="-1"><a class="header-anchor" href="#docker学习记录" aria-hidden="true">#</a> Docker学习记录</h1><p>Docker是一种容器化虚拟技术，通过共用操作系统内核，虚拟出容器，相比较于虚拟机，单个容器耗费的资源更少。</p><h2 id="_1-镜像相关" tabindex="-1"><a class="header-anchor" href="#_1-镜像相关" aria-hidden="true">#</a> 1 镜像相关</h2><h3 id="_1-1-拉取镜像" tabindex="-1"><a class="header-anchor" href="#_1-1-拉取镜像" aria-hidden="true">#</a> 1.1 拉取镜像</h3><p>镜像是用于创建容器的模板，类似光碟。</p>',5),p={href:"https://cr.console.aliyun.com/cn-chengdu/instances/mirrors",target:"_blank",rel:"noopener noreferrer"},m=n(`<p><strong>常用命令</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 拉取一个名为 nginx 的镜像</span>
<span class="token function">docker</span> pull nginx

<span class="token comment"># 查看已有镜像</span>
root@iZ2vcf1lidtliymh8xfkzlZ:~<span class="token comment"># docker images                                                                                              </span>
IMAGE          ID             DISK USAGE   CONTENT SIZE   EXTRA                                                                           
nginx:latest   0d17b565c37b        213MB         <span class="token number">56</span>.7MB

<span class="token comment"># 删除已有的镜像</span>
root@iZ2vcf1lidtliymh8xfkzlZ:~<span class="token comment"># docker rmi nginx                                                                          </span>
Untagged: nginx:latest                                                                                                    
Deleted: sha256:0d17b565c37bcbd895e9d92315a05c1c3c9a29f762b011a10c54a66cd53c9b31
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_1-2-发布镜像" tabindex="-1"><a class="header-anchor" href="#_1-2-发布镜像" aria-hidden="true">#</a> 1.2 发布镜像</h2><h2 id="_2-容器相关" tabindex="-1"><a class="header-anchor" href="#_2-容器相关" aria-hidden="true">#</a> 2 容器相关</h2><p>容器是镜像运行的实例，如基于光碟安装的操作系统。</p><h3 id="_2-1-运行容器" tabindex="-1"><a class="header-anchor" href="#_2-1-运行容器" aria-hidden="true">#</a> 2.1 运行容器</h3><p><strong>常用命令</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 场景一: 运行Nginx容器</span>
<span class="token function">docker</span> run <span class="token punctuation">\\</span>
	<span class="token parameter variable">-d</span> <span class="token punctuation">\\</span> <span class="token comment"># 后台运行</span>
	<span class="token parameter variable">--name</span> nginx-test <span class="token punctuation">\\</span> <span class="token comment"># 给容器命名</span>
	<span class="token parameter variable">-p</span> <span class="token number">8080</span>:80 <span class="token punctuation">\\</span> <span class="token comment"># 端口映射将宿主8080映射到容器80</span>
	<span class="token parameter variable">-p</span> <span class="token number">8443</span>:443 <span class="token punctuation">\\</span> <span class="token comment"># 端口映射将宿主8443映射到容器443</span>
	<span class="token parameter variable">-v</span> /data/nginx/html:/usr/share/nginx/html <span class="token punctuation">\\</span> <span class="token comment"># 挂载卷将宿主的/data/nginx/html挂载到容器内部/usr/share/nginx/html</span>
	<span class="token parameter variable">-v</span> /data/nginx/conf.d:/etc/nginx/conf.d <span class="token punctuation">\\</span> <span class="token comment"># 挂载卷将宿主的/data/nginx/conf.d挂载到容器内部/etc/nginx/conf.d</span>
	nginx:latest

<span class="token comment"># 场景二: 交互式终端运行容器, 退出后删除容器</span>
<span class="token function">docker</span> run <span class="token parameter variable">-it</span> <span class="token parameter variable">--rm</span> alpine:latest <span class="token function">sh</span>

<span class="token comment"># 场景三: 运行一个数据库, 涉及挂载卷和设置环境变量</span>
<span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token punctuation">\\</span>
	<span class="token parameter variable">--name</span> postgres-test <span class="token punctuation">\\</span>
	<span class="token parameter variable">-e</span> <span class="token assign-left variable">POSTGRES_PASSWORD</span><span class="token operator">=</span>mypassword <span class="token punctuation">\\</span>
	<span class="token parameter variable">-e</span> <span class="token assign-left variable">POSTGRES_DB</span><span class="token operator">=</span>mydb <span class="token punctuation">\\</span>
	<span class="token parameter variable">-p</span> <span class="token number">65432</span>:5432 <span class="token punctuation">\\</span>
	<span class="token parameter variable">-v</span> /data/pgdata:/var/lib/postgresql/data <span class="token punctuation">\\</span>
	postgres:17 
	
<span class="token comment"># 查看一个运行中容器的日志</span>
<span class="token function">docker</span> logs <span class="token parameter variable">-f</span> <span class="token operator">&lt;</span>CONTAINER ID<span class="token operator">&gt;</span>

<span class="token comment"># 删除容器通过ID</span>
<span class="token function">docker</span> <span class="token function">rm</span> <span class="token parameter variable">-f</span> <span class="token operator">&lt;</span>CONTAINER ID<span class="token operator">&gt;</span>
root@iZ2vcf1lidtliymh8xfkzlZ:~<span class="token comment"># docker ps                                                                                 </span>
CONTAINER ID   IMAGE           COMMAND   CREATED          STATUS          PORTS     NAMES                                 
d651432c36de   alpine:latest   <span class="token string">&quot;sh&quot;</span>      <span class="token number">18</span> seconds ago   Up <span class="token number">17</span> seconds             vibrant_bassi                         
root@iZ2vcf1lidtliymh8xfkzlZ:~<span class="token comment"># docker rm -f d65                                                                          </span>
d65

<span class="token comment"># 删除容器通过名字</span>
root@iZ2vcf1lidtliymh8xfkzlZ:~<span class="token comment"># docker ps                                                                                 </span>
CONTAINER ID   IMAGE     COMMAND   CREATED         STATUS         PORTS     NAMES                                         
f30bc3b4044b   alpine    <span class="token string">&quot;sh&quot;</span>      <span class="token number">2</span> seconds ago   Up <span class="token number">2</span> seconds             linux-test                                    
root@iZ2vcf1lidtliymh8xfkzlZ:~<span class="token comment"># docker rm -f linux-test                                                                   </span>
linux-test
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>docker run参数速查</p><table><thead><tr><th style="text-align:left;">参数</th><th style="text-align:left;">全称/含义</th><th style="text-align:left;">作用说明</th><th style="text-align:left;">实际应用场景</th><th style="text-align:left;">可选值 / 格式</th></tr></thead><tbody><tr><td style="text-align:left;"><code>-d</code></td><td style="text-align:left;">detach</td><td style="text-align:left;"><strong>后台运行</strong>容器，并返回容器 ID</td><td style="text-align:left;">运行服务端程序（如 Nginx, Redis）</td><td style="text-align:left;"><strong>无</strong>（布尔开关，不需要跟值）</td></tr><tr><td style="text-align:left;"><code>-it</code></td><td style="text-align:left;">interactive + tty</td><td style="text-align:left;"><strong>交互式</strong>运行，分配伪终端</td><td style="text-align:left;">临时进入容器调试、运行临时脚本</td><td style="text-align:left;"><strong>无</strong>（布尔开关，通常 <code>-i</code> 和 <code>-t</code> 连用）</td></tr><tr><td style="text-align:left;"><code>--name</code></td><td style="text-align:left;">name</td><td style="text-align:left;">为容器指定一个<strong>唯一名称</strong></td><td style="text-align:left;">避免每次都要查随机生成的 ID</td><td style="text-align:left;"><strong><code>&lt;自定义名称&gt;</code></strong><br><em>(如：<code>my-nginx</code>，需全局唯一，字母数字下划线)</em></td></tr><tr><td style="text-align:left;"><code>--rm</code></td><td style="text-align:left;">remove</td><td style="text-align:left;">容器退出后<strong>自动删除</strong></td><td style="text-align:left;">用完即弃的临时测试容器</td><td style="text-align:left;"><strong>无</strong>（布尔开关）</td></tr><tr><td style="text-align:left;"><code>-p</code></td><td style="text-align:left;">publish</td><td style="text-align:left;"><strong>端口映射</strong>（宿主机端口:容器端口）</td><td style="text-align:left;">对外提供 Web 服务，如 <code>-p 80:80</code></td><td style="text-align:left;"><strong><code>&lt;宿主机端口&gt;:&lt;容器端口&gt;</code></strong><br><em>(支持：<code>IP:宿主机端口:容器端口</code> 或加 <code>/udp</code>)</em></td></tr><tr><td style="text-align:left;"><code>-v</code></td><td style="text-align:left;">volume</td><td style="text-align:left;"><strong>目录/数据卷挂载</strong>（宿主机:容器）</td><td style="text-align:left;">持久化数据库数据，或挂载配置文件</td><td style="text-align:left;"><strong><code>&lt;宿主机绝对路径&gt;:&lt;容器路径&gt;</code></strong><br><em>(或：<code>&lt;数据卷名&gt;:&lt;容器路径&gt;[:ro]</code>，<code>:ro</code> 为只读)</em></td></tr><tr><td style="text-align:left;"><code>-e</code></td><td style="text-align:left;">env</td><td style="text-align:left;">设置<strong>环境变量</strong></td><td style="text-align:left;">传入数据库密码，如 <code>-e MYSQL_ROOT_PASSWORD=123</code></td><td style="text-align:left;"><strong><code>&lt;变量名&gt;=&lt;变量值&gt;</code></strong><br><em>(可多次使用；也可用 <code>--env-file</code> 指定文件)</em></td></tr><tr><td style="text-align:left;"><code>--network</code></td><td style="text-align:left;">network</td><td style="text-align:left;">指定容器所在的<strong>网络</strong></td><td style="text-align:left;">让多个容器在同一虚拟网络内互通</td><td style="text-align:left;"><strong><code>bridge</code></strong> (默认)、<strong><code>host</code></strong>、<strong><code>none</code></strong> 或 <strong><code>&lt;自定义网络名&gt;</code></strong></td></tr><tr><td style="text-align:left;"><code>--restart</code></td><td style="text-align:left;">restart</td><td style="text-align:left;">设置容器的<strong>重启策略</strong></td><td style="text-align:left;">配合 <code>-d</code> 使用，如 <code>--restart=always</code>（开机自启）</td><td style="text-align:left;"><strong><code>no</code></strong> (默认)、<strong><code>always</code></strong>、<strong><code>on-failure[:最大重试次数]</code></strong>、<strong><code>unless-stopped</code></strong></td></tr><tr><td style="text-align:left;"><code>-w</code></td><td style="text-align:left;">workdir</td><td style="text-align:left;">指定容器内的<strong>工作目录</strong></td><td style="text-align:left;">容器启动后直接进入某个目录执行命令</td><td style="text-align:left;"><strong><code>&lt;容器内绝对路径&gt;</code></strong> <em>(如：<code>-w /app</code>)</em></td></tr><tr><td style="text-align:left;"><code>--entrypoint</code></td><td style="text-align:left;">entrypoint</td><td style="text-align:left;">覆盖镜像默认的<strong>入口点</strong></td><td style="text-align:left;">想改变容器默认行为，比如强制进 Shell 而不跑默认程序</td><td style="text-align:left;"><strong><code>&lt;命令&gt;</code></strong> <em>(如：<code>--entrypoint /bin/bash</code>)</em></td></tr><tr><td style="text-align:left;"><code>--privileged</code></td><td style="text-align:left;">privileged</td><td style="text-align:left;">赋予容器<strong>真正的 root 权限</strong></td><td style="text-align:left;">需要操作宿主机硬件或内核的极少数场景</td><td style="text-align:left;"><strong>无</strong>（布尔开关，⚠️ 生产环境慎用）</td></tr></tbody></table><h3 id="_2-2-创建卷-volume" tabindex="-1"><a class="header-anchor" href="#_2-2-创建卷-volume" aria-hidden="true">#</a> 2.2 创建卷（volume）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 创建卷</span>
<span class="token function">docker</span> volume create my-volume

<span class="token comment"># 使用卷</span>
<span class="token function">docker</span> run <span class="token parameter variable">-it</span> <span class="token parameter variable">--rm</span> <span class="token parameter variable">-v</span> my-volume:/data alpine <span class="token comment"># 如果my-volume未创建则会被隐式创建</span>

<span class="token comment"># 查看卷详细</span>
<span class="token function">docker</span> volume inspect my-volume

<span class="token comment"># 删除指定卷</span>
<span class="token function">docker</span> volume <span class="token function">rm</span> my-volume

<span class="token comment"># 删除未被挂载使用的卷（危险操作！！！）</span>
<span class="token function">docker</span> volume prune
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3" tabindex="-1"><a class="header-anchor" href="#_3" aria-hidden="true">#</a> 3</h2>`,13);function v(g,u){const s=l("ExternalLinkIcon");return d(),i("div",null,[r,e("blockquote",null,[e("p",null,[t("如果遇到网络问题，可以使用阿里云的自带镜像加速。"),e("a",p,[t("容器镜像服务控制台"),o(s)])])]),m])}const k=a(c,[["render",v],["__file","Dockerxuexijilu.html.vue"]]);export{k as default};
